Given a sorted array arr[] and an integer target, find the number of occurrences of target in given array.Examples:Input: arr[] = [1, 1, 2, 2, 2, 2, 3], target = 2Output: 4Explanation: 2 occurs 4 times in the given array.Input: arr[] = [1, 1, 2, 2, 2, 2, 3], target = 4Output: 0Explanation: 4 is not present in the given array.Try It YourselfTable of Content[Naive Approach] Using Linear Search - O(n) Time and O(1) Space[Expected Approach] Using Binary Search - O(log n) Time and O(1) Space[Naive Approach] Using Linear Search - O(n) Time and O(1) SpaceThe idea is to traverse the array and for each element, check if it is equal to the target. If you find any element equal to target increment the value of counter variable.
            C++

    #include <iostream>
#include <vector>
using namespace std;

int countFreq(vector<int> &arr, int target) {
    int res = 0;
    for (int i = 0; i < arr.size(); i++) {

      	// If the current element is equal to 
      	// target, increment the result
        if (arr[i] == target)
            res++;
    }

    return res;
}

int main() {
    vector<int> arr = {1, 1, 2, 2, 2, 2, 3};
    int target = 2;
    cout<< countFreq(arr, target);
    return 0;
}


